+    public void testCreate() throws Exception {
+        Map<String, Object> config = new HashMap<>();
+        List<String> fieldList = randomList(1, 10, () -> randomAlphaOfLength(8));
+        List<String> sortedFieldList = new ArrayList<>(fieldList);
