+        assertThat(fingerprintProcessor.getThreadLocalHasher().get().getAlgorithm(), equalTo(FingerprintProcessor.Factory.DEFAULT_METHOD));
+        assertThat(fingerprintProcessor.isIgnoreMissing(), equalTo(false));
+    }
+}
