+    public void testSalt() throws Exception {
+        var inputMap = new LinkedHashMap<String, Object>();
+        inputMap.put("foo", "foo");
+        doTestFingerprint(inputMap, List.of("foo"), List.of("foo"), "rWTTCYvRPQAzKXydmKwyC+//dmM=", "salt");
+    }
